  Lemma wview_high_some : forall (m : mem) a, AIMG_TOP <= a < 2 ^ 64 -> wview bsegs m (wa a) <> None -> exists b, m (wa a) = Some b.
  Proof.
    intros m a Ha W. unfold AIMG_TOP in Ha. unfold wview in W. destruct (m (wa a)) as [b|] eqn:E; [exists b; reflexivity| exfalso].
    rewrite wa_unsigned in W by lia.
    destruct (find_segment bsegs a 1) as [seg|] eqn:F; [| exact (W eq_refl)].
    apply find_segment_some_spec in F as (IN & B1 & B2). pose proof (bsegs_below_top seg IN). unfold AIMG_TOP in *. lia.
  Qed.

  Lemma rw_cells_CB8_C8' : forall (m : mem) A bs cs, rw_cells bsegs m A (CB 8 bs :: cs) -> exists w, rw_cells bsegs m A (C8 w :: cs).
  Proof.
    intros m A bs cs R. assert (L : length bs = 8%nat) by (destruct R as [[[L _] _] _]; exact L).
    destruct (le8_surj bs L) as [w Hw]. exists w. destruct R as [[[_ W] B] R']. refine (conj (conj (conj I W) _) R').
    cbn [cells_bytes cbytes] in *. rewrite Hw. exact B.
  Qed.

  Lemma pres_record : forall (m : mem) f,
    (forall a, f - 16 <= a < f -> wview bsegs m (wa a) <> None) -> AIMG_TOP + 16 <= f -> f <= 2 ^ 64 ->
    exists v ra, rw_cells bsegs m (f + -16) [C8 (wz v); C8 (wz ra)] /\ 0 <= v < 2 ^ 64 /\ 0 <= ra < 2 ^ 64.
