  Theorem fch_of_presence : forall (m : mem) (sp s0 top bot lo : Z),
    (forall a, lo <= a < top -> wview bsegs m (wa a) <> None) -> AIMG_TOP <= lo -> top <= 2 ^ 64 ->
    lo + 16 <= sp -> sp mod 16 = 0 -> s0 <> sp + 8 ->
    exists CH : list (Z * Z),
